// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address nonOwner, address newOwner) public {
        // nonOwner must be different from the current owner
        vm.assume(nonOwner != c.owner());
        vm.assume(newOwner != c.owner());

        address originalOwner = c.owner();

        vm.prank(nonOwner);
        (bool success,) = address(c).call(abi.encodeWithSignature("setOwner(address)", newOwner));

        // The general rule: if called by a non-owner, the call must revert (success is false)
        // AND the owner must remain unchanged.
        bool ruleHolds = !success && c.owner() == originalOwner;
        assertTrue(ruleHolds);
    }
}

