import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address _newOwner) public {
        // The fuzzer explores the entire address space for the new owner.
        // The default owner of the contract is this contract itself (the setUp deployer).
        // We call setOwner as the current owner.
        vm.prank(address(this));
        bool success = c.setOwner(_newOwner);
        assertTrue(success);

        // After the call, the owner must be the address we passed.
        // The reference version satisfies this for all inputs; the buggy version
        // violates it when _newOwner != address(0).
        assertTrue(c.owner() == _newOwner);
    }
}

