pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner, bool isOriginalOwner) public {
        vm.assume(caller != address(this));
        vm.assume(newOwner != address(0));
        address originalOwner = c.owner();
        vm.assume(isOriginalOwner ? (caller == originalOwner) : (caller != originalOwner));
        vm.prank(caller);
        bool ok;
        try c.setOwner(newOwner) returns (bool success) {
            ok = success;
        } catch {
            ok = false;
        }
        address currentOwner = c.owner();
        if (ok) {
            if (caller == originalOwner) {
                assertEq(currentOwner, newOwner, "Owner should be changed by original owner");
            } else {
                assertEq(currentOwner, originalOwner, "Owner should remain unchanged when non-owner call succeeds (reference reverts)");
            }
        } else {
            assertEq(currentOwner, originalOwner, "Owner should remain unchanged after revert");
        }
    }
}

