pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0));
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);
        // Deploy a helper contract that acts as an adversarial intermediary
        Proxy proxy = new Proxy(c);
        // Original owner is this test contract (msg.sender of setUp -> c.constructor)
        vm.prank(address(this));
        c.setOwner(address(proxy)); // transfer ownership to the proxy to set up the scenario
        // The proxy, when called by anyone, will call setOwner; if the check is tx.origin, it passes as the original deployer (this test contract)
        vm.prank(caller);
        proxy.forward(newOwner);
        // The reference implementation only allows owner changes by the current owner (the proxy),
        // so the original owner (this test contract) could set the proxy as owner, but only the proxy can then change the owner.
        // In the reference, caller (not the original deployer) calling proxy.forward() should fail because proxy is owner and caller != proxy.
        // In the buggy version, tx.origin is this test contract (original deployer), so it succeeds.
        // The invariant: after a call that does not revert, owner must equal the address passed.
        bool success = false;
        try c.setOwner(newOwner) returns (bool) { success = true; } catch { success = false; }
        // If the call succeeds, owner must be newOwner; if it fails, owner should remain the proxy.
        // The general rule: if success, then c.owner() == newOwner; else c.owner() == address(proxy).
        // But we assert a simpler rule: the owner is never caller unless caller explicitly set itself.
        // Actually, we assert: if success, owner == newOwner; if fail, owner == address(proxy).
        // However, we simplify: after the proxy.forward, the owner must NOT equal the caller unless caller == newOwner (which is disallowed by assume).
        // The bug allows caller to become owner. So we assert: c.owner() != caller.
        assertTrue(c.owner() != caller);
    }
}

contract Proxy {
    C public target;
    constructor(C _target) { target = _target; }
    function forward(address newOwner) external { target.setOwner(newOwner); }
}

