        bool success;
        try c.setOwner(nonOwner) returns (bool) {
            success = true;
        } catch {
            success = false;
        }
        // For the reference contract, a non-owner call must revert (success == false).
        // The buggy version allows it, making success == true. Thus, the property
        // "non-owner calls revert" holds for all non-owners on the reference and fails on the buggy one.
        assertFalse(success);
    }
